(* [comment removed for export] *)
Theorem ge_tap_full : forall k c c' s n sp rg md bv,
  ge_avg k c s n -> 0 <= k -> k + 1 <= 2048 -> FB fmt_single 1 sp -> FB fmt_single 1 rg -> 0 <= bv <= 255 ->
  (c' = true -> c = true \/ (sp = p_one_s /\ rg = p_one_s)) ->
  let b := fst (fp_of_int fmt_single md false 32 bv) in
  let kern := fst (fp_mul fmt_single RNE sp rg) in
  let s' := fst (fp_fma fmt_single RNE b kern s) in
  let n' := fst (fp_add fmt_single RNE n kern) in
  ge_avg (k + 1) c' s' n' /\ 0 <= sp < 2 ^ 32 /\ 0 <= rg < 2 ^ 32 /\ 0 <= b < 2 ^ 32 /\ 0 <= kern < 2 ^ 32 /\ 0 <= s' < 2 ^ 32 /\ 0 <= n' < 2 ^ 32.
