(* [comment removed for export] *)
Theorem ge_site_full : forall k s n md1 md2,
  ge_avg k true s n -> 0 <= k <= 2048 ->
  let q := fst (fp_div fmt_single RNE s n) in
  let qd := fst (fp_convert fmt_single fmt_double md1 q) in
  let v := fst (fp_add fmt_double md2 qd p_half_d) in
  0 <= q < 2 ^ 32 /\ 0 <= qd < 2 ^ 64 /\ 0 <= v < 2 ^ 64 /\
  fst (fp_lt fmt_double p_lo_d v) = true /\ fst (fp_lt fmt_double v p_hi_d) = true /\ 0 <= fst (fp_to_int fmt_double RTZ true 32 v) < 256.
